// Router de eventos del bridge: token, trigger #req, continuacion de foto, reacciones, dedupe.
const TOKEN = '660085b0160db3effde5cbb8fe4b6fc5cda3fe70ef79dfe7d959a419f2913d68';
const ALWAYS_CHATS = ['120363410062969047@g.us']; // SOPORTE SISTEMAS
const RE_TRIGGER = /^\s*#(req|ticket|requerimiento)\b[:\-]?\s*/i;
const WINDOW_MS = 5 * 60 * 1000; // ventana de continuacion foto

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.seen)) sd.seen = [];
if (!sd.lastTicket) sd.lastTicket = {};
if (!sd.pendingUndo) sd.pendingUndo = {};
const out = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const p = item.json.body || {};
  if ((headers['x-bridge-token'] || '') !== TOKEN) continue;
  const chat = p.chatJID || '';
  const sender = p.sender || '';
  const key = chat + '|' + sender;

  if (p.eventType === 'reaction') {
    const emoji = p.reactionEmoji || p.content || '';
    if (p.reactionRemoved) continue;
    out.push({ json: { ruta: 'reaccion', chatJID: chat, sender, emoji, recibido: new Date().toISOString() } });
    continue;
  }

  const content = (p.content || '').trim();
  const m = content.match(RE_TRIGGER);
  const isAlways = ALWAYS_CHATS.includes(chat);
  const hasMedia = !!p.mediaBase64;
  const texto = m ? content.replace(RE_TRIGGER, '').trim() : content;
  const lt = sd.lastTicket[key];
  const fresh = lt && (Date.now() - lt.ts) < WINDOW_MS;

  let ruta = null;
  if (hasMedia && fresh && !m && (!texto || texto.length < 20)) {
    ruta = 'continuacion'; // foto suelta poco despues de un ticket del mismo remitente
  } else if (m || isAlways) {
    if (!texto && !hasMedia) continue;
    ruta = 'ticket';
  } else {
    continue;
  }

  // Dedupe: por messageId si existe, sino hash de dia+chat+sender+contenido
  let dedupeKey = p.messageId;
  if (!dedupeKey) {
    const k = `${new Date().toISOString().slice(0, 10)}|${chat}|${sender}|${content}`.slice(0, 500);
    let h = 0;
    for (let i = 0; i < k.length; i++) h = ((h << 5) - h + k.charCodeAt(i)) | 0;
    dedupeKey = 'h' + h;
  }
  if (sd.seen.includes(dedupeKey)) continue;
  sd.seen.push(dedupeKey);
  if (sd.seen.length > 300) sd.seen = sd.seen.slice(-200);

  const base = {
    ruta,
    texto,
    sender,
    chatJID: chat,
    isFromMe: !!p.isFromMe,
    msgId: p.messageId || '',
    quotedContent: p.quotedContent || '',
    quotedSender: p.quotedSender || '',
    mediaBase64: p.mediaBase64 || '',
    mimeType: p.mimeType || '',
    mediaFilename: p.mediaFilename || '',
    recibido: new Date().toISOString()
  };
  if (ruta === 'continuacion') {
    out.push({ json: { ...base, cardId: lt.cardId, cardName: lt.cardName, shortUrl: lt.shortUrl } });
  } else {
    out.push({ json: base });
  }
}
return out;

